def solve(s):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if stack == [] or mapping[char] != stack.pop():
                return False
        else:
            return False
    return stack == []

# Example usage
print(solve("()"))  # True
print(solve("()[]{}"))  # True
print(solve("(]"))  # False
print(solve("([)]"))  # False
print(solve("{[]}"))  # True
```

